const d = $input.first().json.body;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const filas = d.items.map(i => {
  const resultado = i.resultado === 'COMPRADO'
    ? 'Comprado — ' + esc(i.proveedor)
    : 'Rechazado por ' + esc(i.rechazadoPor) + ' — ' + esc(i.motivoRechazo);
  return '<tr><td>' + esc(i.categoria) + '</td><td>' + esc(i.detalle) + '</td><td>' + resultado + '</td></tr>';
}).join('');
const html = '<p>Hola ' + esc(d.solicitanteNombre) + ', tu solicitud #' + d.solicitudId + ' ya fue resuelta:</p>'
  + '<table border="1" cellpadding="6" cellspacing="0"><tr><th>Categoría</th><th>Ítem</th><th>Resultado</th></tr>'
  + filas + '</table>';
return [{ json: { solicitanteEmail: d.solicitanteEmail, solicitudId: d.solicitudId, html } }];
